using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsInspectorOperations
{
    private readonly PhysicsGeometryOperations _geometry=new();
    public Control? editor(RefCounted owner){foreach(var editor in Host(owner).GetTree().GetNodesInGroup("actor_timeline_editors"))if(editor.Get("model").AsGodotObject()==Model(owner))return editor as Control;return null;}
    public void target(RefCounted owner,string key,string boneKey,string title,VBoxContainer parent){property(owner,key,title,parent,false);var choose=new OptionButton{Name="Physics_"+key,FitToLongestItem=false};parent.AddChild(choose);choose.AddItem("World / animated actor");choose.SetItemMetadata(0,"");var model=Model(owner);var actor=Actor(owner);var settings=Initial(owner);foreach(var value in model.Get("actors").AsGodotArray()){var candidate=value.As<Resource>();if(candidate==actor||!_settings.compatible(candidate))continue;choose.AddItem(candidate.Get("display_name").AsString());choose.SetItemMetadata(choose.ItemCount-1,candidate.Get("id"));}int selected=-1;for(int i=0;i<choose.ItemCount;i++)if(choose.GetItemMetadata(i).AsString()==settings[key].AsString())selected=i;if(selected<0){choose.AddItem("⚠ Missing actor");choose.SetItemMetadata(choose.ItemCount-1,settings[key].AsString());selected=choose.ItemCount-1;}choose.Select(selected);choose.ItemSelected+=index=>change(owner,key,choose.GetItemMetadata((int)index).AsString(),true);var target=model.Call("actor_for_id",settings[key].AsString()).As<Resource>();if(target==null)return;var definitions=Get(target.Get("values").AsGodotDictionary(),"rig_bones",new GArray()).AsGodotArray();if(definitions.Count==0)return;var bones=new OptionButton{Name="Physics_"+boneKey,FitToLongestItem=false};bones.AddItem("Actor origin");bones.SetItemMetadata(0,"");parent.AddChild(bones);foreach(var value in definitions){string name=value.AsGodotDictionary()["name"].AsString();bones.AddItem(name);bones.SetItemMetadata(bones.ItemCount-1,name);}bool found=false;for(int i=0;i<bones.ItemCount;i++)if(bones.GetItemMetadata(i).AsString()==settings[boneKey].AsString()){bones.Select(i);found=true;}if(!found){bones.AddItem("⚠ Missing: "+settings[boneKey].AsString());bones.SetItemMetadata(bones.ItemCount-1,settings[boneKey].AsString());bones.Select(bones.ItemCount-1);}bones.ItemSelected+=index=>change(owner,boneKey,bones.GetItemMetadata((int)index).AsString(),true);}
    private void StructuredNumber(RefCounted owner,SpinBox input,string field,Func<double,Variant> amend){var actor=Actor(owner);var model=Model(owner);var gesture=new Gesture();void Restore(){actor.Get("values").AsGodotDictionary()[new StringName("physics")]=gesture.Before;gesture.Active=false;}input.Connect("interaction_started",Callable.From(()=>{gesture.Before=_settings.authored(actor);gesture.Active=true;}));input.Connect("preview_changed",Callable.From<double>(value=>{var data=_settings.authored(actor);data[field]=amend(value);actor.Get("values").AsGodotDictionary()[new StringName("physics")]=data;model.EmitSignal("changed");}));input.Connect("drag_committed",Callable.From<double>(value=>{if(gesture.Active)Restore();change(owner,field,amend(value),false);}));input.Connect("drag_cancelled",Callable.From(()=>{if(gesture.Active){Restore();model.EmitSignal("changed");}}));input.ValueChanged+=value=>change(owner,field,amend(value),false);input.Connect("interaction_ended",Callable.From(()=>{if(gesture.Active&&Mathf.IsEqualApprox(input.Value,input.Get("_origin").AsDouble())){Restore();model.EmitSignal("changed");}}));}
    public void structured_number(RefCounted owner,SpinBox input,string field,Variant amend)=>StructuredNumber(owner,input,field,value=>owner.Call("_amend",amend,value));
    public void events(RefCounted owner){var parent=fold(owner,"Forces and impulses");var add=new Button{Text="＋ Force / impulse event"};parent.AddChild(add);var actor=Actor(owner);add.Pressed+=()=>{var events=_settings.authored(actor)["forces"].AsGodotArray().Duplicate(true);double at=actor.Get("animation_time").AsDouble();events.Add(new Settings{["time"]=double.IsNaN(at)?0:Math.Max(0,at),["duration"]=0.0,["impulse"]=new Vector3(0,3,0),["force"]=Vector3.Zero});change(owner,"forces",events,true);};var source=Initial(owner)["forces"].AsGodotArray();for(int index=0;index<source.Count;index++){int eventIndex=index;var item=source[index].AsGodotDictionary();var group=new VBoxContainer();parent.AddChild(group);var remove=new Button{Text="× Event "+(index+1)};group.AddChild(remove);remove.Pressed+=()=>{var events=_settings.authored(actor)["forces"].AsGodotArray().Duplicate(true);events.RemoveAt(eventIndex);change(owner,"forces",events,true);};foreach(string field in new[]{"time","duration","impulse","force"}){string key=field;bool vector=field is "impulse" or "force";Host(owner).Call("_add_label",group,field switch{"time"=>"Source time (s)","duration"=>"Force duration (s)","impulse"=>"Impulse (X / Y / Z)",_=>"Force (X / Y / Z)"});var row=new HBoxContainer();group.AddChild(row);for(int axis=0;axis<(vector?3:1);axis++){int component=axis;var input=Number();input.Step=.01;input.AllowGreater=true;input.AllowLesser=vector;input.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;row.AddChild(input);input.SetValueNoSignal(vector?Get(item,key,Vector3.Zero).AsVector3()[axis]:Get(item,key,0).AsDouble());StructuredNumber(owner,input,"forces",value=>{var events=_settings.authored(actor)["forces"].AsGodotArray().Duplicate(true);if(eventIndex>=events.Count)return events;var data=events[eventIndex].AsGodotDictionary();if(vector){var next=data[key].AsVector3();next[component]=(float)value;data[key]=next;}else data[key]=value;return events;});}}}}
    public void pins(RefCounted owner){var controls=fold(owner,"Point pins");var view=editor(owner);var actor=Actor(owner);var pick=new CheckButton{Text="Pick pins in viewport",ButtonPressed=actor.GetMeta("editor_physics_pin_mode",false).AsBool()};controls.AddChild(pick);pick.Toggled+=value=>actor.SetMeta("editor_physics_pin_mode",value);var point=Number();point.MinValue=0;point.MaxValue=255;point.Step=1;point.SetValueNoSignal(0);controls.AddChild(point);var add=new Button{Text="Pin simulation point"};controls.AddChild(add);add.Pressed+=()=>{if(view==null)return;var physics=view.Get("physics").AsGodotObject();var prototypes=physics.Get("prototypes").AsGodotDictionary();string id=actor.Get("id").AsString();if(!prototypes.ContainsKey(id))return;var prototype=prototypes[id].AsGodotDictionary();var graph=prototype["graph"].AsGodotDictionary();if(graph.Count==0){graph=_geometry.particles(prototype["geometry"].AsGodotDictionary(),Initial(owner)["particles"].AsInt32(),physics.Call("animated_world",id,Model(owner).Get("playhead_time")).AsTransform3D());prototype["graph"]=graph;}if(Get(graph,"error","").AsString().Length>0)return;var display=Get(physics.Get("display_states").AsGodotDictionary(),id,new Settings()).AsGodotDictionary();var points=Get(display,"points",graph["rest"]).AsVector3Array();if(points.Length==0)return;int index=Math.Clamp((int)point.Value,0,points.Length-1);_settings.pin(view,actor,index,points[index],false);Host(owner).Call("_queue_rebuild_selected");};var source=Initial(owner)["pins"].AsGodotArray();for(int i=0;i<source.Count;i++){int index=i;var pin=source[i].AsGodotDictionary();var remove=new Button{Text="× Point "+Get(pin,"point",0).AsInt64()+" · "+(Get(pin,"actor","").AsString().Length==0?"World":"Attached")};controls.AddChild(remove);remove.Pressed+=()=>{var pins=_settings.authored(actor)["pins"].AsGodotArray().Duplicate(true);pins.RemoveAt(index);change(owner,"pins",pins,true);};}}
}
